package com.beeboee.magnot.region;import net.minecraft.nbt.CompoundNBT;import net.minecraft.util.math.*;import net.minecraft.util.math.vector.Vector3d;import java.util.*;public final class FerrousRegion{private static final double EPS=1e-12;private final UUID id,groupId;private final BlockPos min,max;public FerrousRegion(UUID id,UUID groupId,BlockPos min,BlockPos max){this.id=id;this.groupId=groupId;this.min=min;this.max=max;}public FerrousRegion(UUID id,BlockPos min,BlockPos max){this(id,id,min,max);}public static FerrousRegion fromCorners(BlockPos a,BlockPos b){UUID id=UUID.randomUUID();return fromCorners(id,a,b);}public static FerrousRegion fromCorners(UUID id,BlockPos a,BlockPos b){return new FerrousRegion(id,id,new BlockPos(Math.min(a.getX(),b.getX()),Math.min(a.getY(),b.getY()),Math.min(a.getZ(),b.getZ())),new BlockPos(Math.max(a.getX(),b.getX()),Math.max(a.getY(),b.getY()),Math.max(a.getZ(),b.getZ())));}public UUID id(){return id;}public UUID groupId(){return groupId;}public BlockPos min(){return min;}public BlockPos max(){return max;}public AxisAlignedBB bounds(){return new AxisAlignedBB(min.getX(),min.getY(),min.getZ(),max.getX()+1,max.getY()+1,max.getZ()+1);}public boolean contains(Vector3d p){return bounds().contains(p);}public boolean intersects(Vector3d a,Vector3d b){return hitDistanceSqr(a,b).isPresent();}public Optional<Double> hitDistanceSqr(Vector3d a,Vector3d b){AxisAlignedBB box=bounds();double lo=0,hi=1;double[] s={a.x,a.y,a.z},d={b.x-a.x,b.y-a.y,b.z-a.z},mn={box.minX,box.minY,box.minZ},mx={box.maxX,box.maxY,box.maxZ};for(int i=0;i<3;i++){if(Math.abs(d[i])<EPS){if(s[i]<mn[i]||s[i]>mx[i])return Optional.empty();continue;}double x=(mn[i]-s[i])/d[i],y=(mx[i]-s[i])/d[i];if(x>y){double q=x;x=y;y=q;}lo=Math.max(lo,x);hi=Math.min(hi,y);if(lo>hi)return Optional.empty();}return hi<0||lo>1?Optional.empty():Optional.of(a.distanceToSqr(b)*Math.max(0,lo)*Math.max(0,lo));}public CompoundNBT save(){CompoundNBT t=new CompoundNBT();t.putUUID("Id",id);t.putUUID("GroupId",groupId);t.putInt("MinX",min.getX());t.putInt("MinY",min.getY());t.putInt("MinZ",min.getZ());t.putInt("MaxX",max.getX());t.putInt("MaxY",max.getY());t.putInt("MaxZ",max.getZ());return t;}public static FerrousRegion load(CompoundNBT t){UUID id=t.hasUUID("Id")?t.getUUID("Id"):UUID.randomUUID(),group=t.hasUUID("GroupId")?t.getUUID("GroupId"):id;return new FerrousRegion(id,group,new BlockPos(t.getInt("MinX"),t.getInt("MinY"),t.getInt("MinZ")),new BlockPos(t.getInt("MaxX"),t.getInt("MaxY"),t.getInt("MaxZ")));}}
